<script>import {config,preferences,auth,request,notify,exportDiagnostics,snapshot} from '../state.js';import {copy,download,date} from '../lib.js';import Icon from '../components/Icon.svelte';import Check from '../components/Check.svelte';let tab='general',busy='',diagnostic=null,error='',sourceOpen=false;async function action(name){if(busy)return;busy=name;error='';try{if(name==='test'){await request('notifications/test',{method:'POST',body:'{}'});notify('テスト通知を送信しました');}else if(name==='doctor')diagnostic=await request('doctor',{method:'POST',body:'{}'});else if(name==='export')download('scyllascope-diagnostics.json',await exportDiagnostics());}catch(e){error=e.message;notify(e.message,'error');}finally{busy='';}}const example=`# /etc/scyllascope/config.yaml（既存の認証情報は保持）\nmonitoring:\n  expected_nodes: 3\n  interval: 10s\n  timeout: 3s\n  failure_window: 3\n  recovery_window: 2\n# 全観測ノードで同じ値を設定\n# cluster_token: "openssl rand -hex 32 で一度だけ生成した値"\nnotifications:\n  discord_webhook: ""\n  generic_webhook: ""\n# 変更後: sudo systemctl restart scyllascope\n`;</script>
<section class="panel"><nav class="tabs settings-tabs" aria-label="設定タブ">{#each [['general','表示'],['monitor','監視・通知'],['security','接続・セキュリティ'],['diagnostics','診断']] as [id,label]}<button class:active={tab===id} onclick={()=>tab=id}>{label}</button>{/each}</nav><div class="settings-body">
<section hidden={tab!=='general'}><h2>このブラウザの表示設定</h2><p class="hint">サーバーの監視設定とは別に保存されます。自動更新中も変更を維持します。</p><div class="settings-row"><div><strong>テーマ</strong><p>ダーク / ライト</p></div><select aria-label="テーマ" value={$preferences.theme} onchange={e=>preferences.update(p=>({...p,theme:e.target.value}))}><option value="dark">ダーク</option><option value="light">ライト</option></select></div><div class="settings-row"><div><strong>情報密度</strong><p>既定はコンパクト。操作領域を広くする場合は標準。</p></div><select aria-label="情報密度" value={$preferences.density} onchange={e=>preferences.update(p=>({...p,density:e.target.value}))}><option value="compact">コンパクト</option><option value="comfortable">標準</option></select></div><div class="settings-row"><div><strong>ショートカット</strong><p>Alt + 1〜8: ページ切替 / Esc: 詳細を閉じる / Ctrl + Enter: CQL実行</p></div></div></section>
<section hidden={tab!=='monitor'}><h2>実行中の監視設定</h2><p class="hint">サーバー設定は読み取り表示です。反映には設定ファイルを編集してScopeのみ再起動します。</p><dl class="definition"><dt>監視間隔 / タイムアウト</dt><dd>{$config?.interval} / {$config?.timeout}</dd><dt>異常確定 / 復旧確定</dt><dd>{$config?.failure_window}回 / {$config?.recovery_window}回</dd><dt>期待するメンバー数</dt><dd>{$config?.expected_nodes||'自動検出'}</dd><dt>保存期間 / サンプル間隔</dt><dd>{$config?.history_hours}時間 / {$config?.sample_interval}</dd><dt>Discord</dt><dd>{$config?.notifications?.discord?'設定済み':'未設定'}</dd><dt>汎用Webhook</dt><dd>{$config?.notifications?.generic?'設定済み':'未設定'}</dd><dt>通知元</dt><dd>{$config?.notifications?.sender_node||'各観測ノードが自分の結果を通知'}</dd></dl><button disabled={!$auth?.authenticated||busy!==''||!($config?.notifications?.discord||$config?.notifications?.generic)} onclick={()=>action('test')}><Icon name="alerts" size={15}/>{busy==='test'?'送信中':'テスト通知'}</button><details class="config-example"><summary>設定例を表示</summary><pre>{example}</pre><p class="hint">例を丸ごと既存ファイルに上書きしないでください。認証トークン・CQL認証・通知URLを消さないよう、必要な項目だけ変更します。</p><button onclick={()=>download('scyllascope-monitoring-example.yaml',example,'text/yaml')}>設定例を保存</button></details></section>
<section hidden={tab!=='security'}><h2>接続・認証</h2><dl class="definition"><dt>UI認証</dt><dd>{$config?.ui_auth_configured?'有効（共有管理トークン）':'無効・読取専用'}</dd><dt>ノード間の認証</dt><dd>{$config?.peer_auth_configured?'設定済み':'未設定（状態共有しません）'}</dd><dt>CQLコンソール</dt><dd>{$config?.console_enabled?'有効・SELECTのみ':'無効'}</dd><dt>Scope待受</dt><dd class="mono">{$config?.listen}</dd><dt>CQL接続先</dt><dd class="mono">{($config?.cql_hosts||[]).join(', ')}:{$config?.cql_port}</dd><dt>ノード間 / メトリクス</dt><dd>{$config?.internode_port} / {$config?.prometheus_port}</dd><dt>Scylla REST</dt><dd class="mono wrap">{$config?.rest_url}</dd></dl><details bind:open={sourceOpen}><summary>設定の読み取り元</summary><dl class="definition"><dt>Scope override</dt><dd class="mono wrap">{$config?.config_source}</dd><dt>Scyllaの実設定</dt><dd class="mono wrap">{$config?.scylla_config}</dd></dl></details><p class="notice">管理UIはTailscaleなどの信頼できるネットワーク内に限定してください。多人数のRBAC・SSO・操作承認ワークフローは、この版には含めていません。</p></section>
<section hidden={tab!=='diagnostics'}><h2>読み取り専用の診断</h2><p class="hint">接続・メンバー取得・監視の範囲を再確認します。DBの再起動やrepairは実行しません。</p><div class="button-group"><button class="primary" disabled={!$auth?.authenticated||busy!==''} onclick={()=>action('doctor')}><Icon name="shield" size={15}/>{busy==='doctor'?'診断中':'診断を実行'}</button><button disabled={busy!==''} onclick={()=>action('export')}><Icon name="download" size={15}/>診断JSON</button></div><p class="hint">出力にはIP・ノード名を含みます。共有前に確認してください。パスワード・トークン・DB行データは出力しません。</p>{#if diagnostic}<div class="diagnostic"><h3>診断結果 · {date(diagnostic.checked_at)}</h3><div class="checks-list"><div><span>クラスタ一覧</span><Check value={diagnostic.discovery} ttl={$snapshot?.stale_after_seconds}/></div></div>{#each diagnostic.nodes||[] as n (n.id)}<div class="diagnostic-node"><strong>{n.name}</strong><Check value={n.cql} caption="CQL"/><Check value={n.internode} caption="7000"/></div>{/each}{#each diagnostic.warnings||[] as w}<p class="hint">{w}</p>{/each}<details><summary>JSONを見る</summary><pre>{JSON.stringify(diagnostic,null,2)}</pre></details></div>{/if}</section>
{#if error}<p class="error-text" role="alert">{error}</p>{/if}
</div></section>
